"""Central pytest classification and Task 4 necessity audit metadata.

Every behavior test file is registered explicitly. Resource flags are audit evidence
only; no layer/domain is inferred dynamically from source text.
"""
from __future__ import annotations

PRIMARY_LAYERS = {"unit", "contract", "integration"}
ORTHOGONAL_MARKERS = {"smoke", "slow", "serial"}
DOMAIN_MARKERS = {"base", "runtime", "workflow", "cards", "knowledge", "wiki", "autonomy", "roles", "migration", "release", "portability"}
NECESSITY_CLASSES = {"KEEP_INDEPENDENT_CONTRACT", "KEEP_REGRESSION", "MERGE_CANDIDATE", "SUPERSEDED_CANDIDATE"}
_RESOURCE_NAMES = ("subprocess", "sqlite", "git", "network", "port", "shared_temp", "env_mutation", "cwd_mutation")

def _case(layer: str, domains: tuple[str, ...], necessity: str, main_contracts: str, *, resources: tuple[str, ...] = (), parallel: str = "YES", slow: bool = False, serial: bool = False) -> dict:
    resource_set = set(resources)
    unknown = resource_set - set(_RESOURCE_NAMES)
    if unknown:
        raise ValueError(f"unknown test resource flags: {sorted(unknown)}")
    return {
        "layer": layer,
        "domains": domains,
        "necessity": necessity,
        "parallel_candidate": parallel,
        "resources": {name: name in resource_set for name in _RESOURCE_NAMES},
        "main_contracts": main_contracts,
        "slow": slow,
        "serial": serial,
    }

