def metadata_for_path(path: str) -> dict:
    """Return registered metadata or fail closed for a newly added test file."""
    try:
        return TEST_FILE_CATALOG[path]
    except KeyError as exc:
        raise KeyError(f"unregistered test file: {path}") from exc
